<?php
require_once __DIR__ . '/../config/config.php';
require_roles(['ADMIN', 'HR']);
$pdo = db(); $id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT) ?: null; $action = $_GET['action'] ?? ($id ? 'edit' : 'list'); $error = null;
$departments = $pdo->query('SELECT id,name FROM departments WHERE is_active=1 ORDER BY name')->fetchAll(); $positions = $pdo->query('SELECT id,name FROM positions WHERE is_active=1 ORDER BY name')->fetchAll(); $branches = $pdo->query('SELECT id,name FROM branches WHERE is_active=1 ORDER BY name')->fetchAll();
$employee = null;
if ($id) { $statement = $pdo->prepare('SELECT * FROM employees WHERE id=?'); $statement->execute([$id]); $employee = $statement->fetch(); if (!$employee) { flash('error','Employee not found.'); redirect('admin/employees.php'); } }
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf();
    if (($_POST['form_action'] ?? '') === 'delete') { $deleteId = (int) $_POST['id']; $pdo->prepare('DELETE FROM employees WHERE id=?')->execute([$deleteId]); audit('DELETE','employees',$deleteId); flash('success','Employee record deleted.'); redirect('admin/employees.php'); }
    $data = [post_value('employee_number'), post_value('first_name'), post_value('middle_name'), post_value('last_name'), post_value('suffix'), valid_date(post_value('date_of_birth')), post_value('gender'), post_value('civil_status'), post_value('email'), post_value('phone'), post_value('address'), (int) ($_POST['department_id'] ?? 0) ?: null, (int) ($_POST['position_id'] ?? 0) ?: null, (int) ($_POST['branch_id'] ?? 0) ?: null, post_value('employment_status') ?: 'Active', valid_date(post_value('date_hired')), post_value('employment_type') ?: 'Regular'];
    if (!$data[0] || !$data[1] || !$data[3]) $error = 'Employee ID, first name, and last name are required.'; else { try { if ($id) { $pdo->prepare('UPDATE employees SET employee_number=?,first_name=?,middle_name=?,last_name=?,suffix=?,date_of_birth=?,gender=?,civil_status=?,email=?,phone=?,address=?,department_id=?,position_id=?,branch_id=?,employment_status=?,date_hired=?,employment_type=? WHERE id=?')->execute([...$data,$id]); audit('UPDATE','employees',$id); flash('success','Employee record updated.'); } else { $pdo->prepare('INSERT INTO employees (employee_number,first_name,middle_name,last_name,suffix,date_of_birth,gender,civil_status,email,phone,address,department_id,position_id,branch_id,employment_status,date_hired,employment_type) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute($data); $newId=(int)$pdo->lastInsertId(); audit('CREATE','employees',$newId); flash('success','Employee record created.'); } redirect('admin/employees.php'); } catch (PDOException $exception) { $error = 'Could not save the record. Check that the employee ID and email are unique.'; } }
}
$pageTitle = $action === 'list' ? 'Employees' : ($id ? 'Edit employee' : 'Add employee'); require __DIR__ . '/../includes/header.php';
if ($action !== 'list'): $employee = $employee ?: $_POST; ?><div class="mb-6"><a href="<?= url('admin/employees.php') ?>" class="text-sm font-bold text-teal-700">← Back to employees</a><h1 class="font-display text-3xl font-bold mt-3"><?= e($pageTitle) ?></h1></div><?php if ($error): ?><div class="mb-6 rounded-lg bg-red-50 border border-red-200 p-3 text-sm text-red-700"><?= e($error) ?></div><?php endif; ?><form method="post" class="bg-white border border-slate-200 rounded-xl p-6 lg:p-8"><?= csrf_field() ?><div class="grid md:grid-cols-3 gap-5"><label class="text-sm font-semibold">Employee ID<input required name="employee_number" value="<?= e($employee['employee_number'] ?? '') ?>" class="field"></label><label class="text-sm font-semibold">First name<input required name="first_name" value="<?= e($employee['first_name'] ?? '') ?>" class="field"></label><label class="text-sm font-semibold">Middle name<input name="middle_name" value="<?= e($employee['middle_name'] ?? '') ?>" class="field"></label><label class="text-sm font-semibold">Last name<input required name="last_name" value="<?= e($employee['last_name'] ?? '') ?>" class="field"></label><label class="text-sm font-semibold">Suffix<input name="suffix" value="<?= e($employee['suffix'] ?? '') ?>" class="field"></label><label class="text-sm font-semibold">Date of birth<input type="date" name="date_of_birth" value="<?= e($employee['date_of_birth'] ?? '') ?>" class="field"></label><label class="text-sm font-semibold">Gender<select name="gender" class="field"><option value="">Select</option><?php foreach(['Female','Male','Non-binary','Prefer not to say'] as $option): ?><option <?= ($employee['gender'] ?? '') === $option ? 'selected' : '' ?>><?= e($option) ?></option><?php endforeach; ?></select></label><label class="text-sm font-semibold">Civil status<select name="civil_status" class="field"><option value="">Select</option><?php foreach(['Single','Married','Widowed','Separated'] as $option): ?><option <?= ($employee['civil_status'] ?? '') === $option ? 'selected' : '' ?>><?= e($option) ?></option><?php endforeach; ?></select></label><label class="text-sm font-semibold">Email<input type="email" name="email" value="<?= e($employee['email'] ?? '') ?>" class="field"></label><label class="text-sm font-semibold">Phone<input name="phone" value="<?= e($employee['phone'] ?? '') ?>" class="field"></label><label class="text-sm font-semibold md:col-span-2">Address<input name="address" value="<?= e($employee['address'] ?? '') ?>" class="field"></label><label class="text-sm font-semibold">Department<select name="department_id" class="field"><option value="">Select</option><?php foreach($departments as $item): ?><option value="<?= e($item['id']) ?>" <?= (string)($employee['department_id'] ?? '') === (string)$item['id'] ? 'selected' : '' ?>><?= e($item['name']) ?></option><?php endforeach; ?></select></label><label class="text-sm font-semibold">Position<select name="position_id" class="field"><option value="">Select</option><?php foreach($positions as $item): ?><option value="<?= e($item['id']) ?>" <?= (string)($employee['position_id'] ?? '') === (string)$item['id'] ? 'selected' : '' ?>><?= e($item['name']) ?></option><?php endforeach; ?></select></label><label class="text-sm font-semibold">Branch<select name="branch_id" class="field"><option value="">Select</option><?php foreach($branches as $item): ?><option value="<?= e($item['id']) ?>" <?= (string)($employee['branch_id'] ?? '') === (string)$item['id'] ? 'selected' : '' ?>><?= e($item['name']) ?></option><?php endforeach; ?></select></label><label class="text-sm font-semibold">Employment status<select name="employment_status" class="field"><?php foreach(['Active','Probationary','On Leave','Separated'] as $option): ?><option <?= ($employee['employment_status'] ?? 'Active') === $option ? 'selected' : '' ?>><?= e($option) ?></option><?php endforeach; ?></select></label><label class="text-sm font-semibold">Date hired<input type="date" name="date_hired" value="<?= e($employee['date_hired'] ?? '') ?>" class="field"></label><label class="text-sm font-semibold">Employment type<select name="employment_type" class="field"><?php foreach(['Regular','Probationary','Contractual','Part-time'] as $option): ?><option <?= ($employee['employment_type'] ?? 'Regular') === $option ? 'selected' : '' ?>><?= e($option) ?></option><?php endforeach; ?></select></label></div><div class="mt-8 flex justify-end gap-3"><a href="<?= url('admin/employees.php') ?>" class="rounded-lg border px-5 py-3 text-sm font-bold">Cancel</a><button class="rounded-lg bg-teal-700 px-5 py-3 text-sm font-bold text-white">Save employee</button></div></form><?php else: $employees = $pdo->query('SELECT e.*, d.name AS department_name, p.name AS position_name, b.name AS branch_name FROM employees e LEFT JOIN departments d ON d.id=e.department_id LEFT JOIN positions p ON p.id=e.position_id LEFT JOIN branches b ON b.id=e.branch_id ORDER BY e.last_name,e.first_name')->fetchAll(); ?><div class="flex flex-col md:flex-row md:items-end md:justify-between gap-4 mb-8"><div><p class="text-sm text-slate-500">Authoritative employee master records</p><h1 class="font-display text-3xl font-bold mt-1">Employees</h1></div><a href="?action=create" class="rounded-lg bg-teal-700 px-5 py-3 text-sm font-bold text-white">+ Add employee</a></div><div class="bg-white border border-slate-200 rounded-xl overflow-x-auto"><table class="w-full text-left text-sm"><thead class="text-xs uppercase text-slate-400 bg-slate-50"><tr><th class="px-6 py-4">Employee</th><th class="px-6 py-4">Department / position</th><th class="px-6 py-4">Branch</th><th class="px-6 py-4">Status</th><th class="px-6 py-4 text-right">Actions</th></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach($employees as $item): ?><tr><td class="px-6 py-4"><p class="font-bold"><?= e($item['first_name'].' '.$item['last_name']) ?></p><p class="text-xs text-slate-400"><?= e($item['employee_number']) ?> · <?= e($item['email'] ?? 'No email') ?></p></td><td class="px-6 py-4"><?= e($item['department_name'] ?? 'Unassigned') ?><p class="text-xs text-slate-400"><?= e($item['position_name'] ?? 'Unassigned') ?></p></td><td class="px-6 py-4"><?= e($item['branch_name'] ?? 'Unassigned') ?></td><td class="px-6 py-4"><span class="rounded-full bg-emerald-50 px-3 py-1 text-xs font-bold text-emerald-700"><?= e($item['employment_status']) ?></span></td><td class="px-6 py-4 text-right"><a class="font-bold text-teal-700" href="?action=edit&id=<?= e($item['id']) ?>">Edit</a><form class="inline" method="post"><?= csrf_field() ?><input type="hidden" name="form_action" value="delete"><input type="hidden" name="id" value="<?= e($item['id']) ?>"><button data-confirm="Delete this employee record?" class="ml-4 font-bold text-red-600">Delete</button></form></td></tr><?php endforeach; ?></tbody></table><?php if (!$employees): ?><p class="p-10 text-center text-slate-500">No employee records yet.</p><?php endif; ?></div><?php endif; require __DIR__ . '/../includes/footer.php';